// Tous les nombres des mises en situation sont fictifs et servent uniquement à l'exercice.
const D='debutant', I='intermediaire', A='avance';
const base=(theme,n,level,concept,kind,prompt,answer,explanation)=>({id:`author-${theme}-${n}`,theme,level,concept:`notion-${concept}`,kind,prompt,answer,explanation});
// Dans C, la première option est la réponse rédigée ; l'interface mélange les options.
const C=(t,n,l,c,p,options,e)=>({...base(t,n,l,c,'choice',p,options[0],e),options});
const T=(t,n,l,c,p,answer,e)=>({...base(t,n,l,c,'choice',p,answer?'Vrai':'Faux',e),options:['Vrai','Faux']});
const N=(t,n,l,c,p,answer,e)=>base(t,n,l,c,'number',p,answer,e);
const O=(t,n,l,c,p,answer,e)=>base(t,n,l,c,'order',p,answer,e);
const M=(t,n,l,c,p,labels,answer,e)=>({...base(t,n,l,c,'matching',p,answer,e),labels});

